CREATE OR REPLACE FUNCTION public.enqueue_notification_push() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ BEGIN IF NEW.recipient_staff_id IS NOT NULL THEN INSERT INTO public.notification_delivery_outbox(notification_id, recipient_staff_id) VALUES (NEW.id, NEW.recipient_staff_id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$; CREATE TRIGGER enqueue_notification_push_after_insert AFTER INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.enqueue_notification_push();